import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuthStore } from '@/store/auth.store';
import { supabase } from '@/lib/supabase';
import type { MovementPermit } from '@/types/facility';
import s from './quarantine.module.css';

interface AnimalEntry {
  tag_number: string;
  species: string;
  arrival_condition: 'HEALTHY' | 'SICK' | 'INJURED' | 'DEAD';
  notes: string;
}

function genCode(facilityCode: string): string {
  const n = Math.floor(Math.random() * 900000 + 100000);
  return `${facilityCode}-QB-${n}`;
}

export function AnimalArrivalPage(): JSX.Element {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { facilityId, facilityCode, staffId, staffName } = useAuthStore();

  const [permit, setPermit]   = useState<MovementPermit | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving]   = useState(false);
  const [error, setError]     = useState<string | null>(null);
  const [step, setStep]       = useState(1); // 1=Verify, 2=Scan Animals, 3=Confirm

  // Step 1 fields — pre-filled from permit where available
  const [vehicleReg, setVehicleReg]   = useState('');
  const [driverName, setDriverName]   = useState('');
  const [sealNumber, setSealNumber]   = useState('');
  const [permitQr, setPermitQr]       = useState('');

  // Step 2 fields
  const [animals, setAnimals]         = useState<AnimalEntry[]>([]);
  const [tagInput, setTagInput]       = useState('');
  const [speciesInput, setSpeciesInput] = useState('CATTLE');
  const [conditionInput, setConditionInput] = useState<AnimalEntry['arrival_condition']>('HEALTHY');
  const [notesInput, setNotesInput]   = useState('');

  // Step 3 fields
  const [penAssignment, setPenAssignment]         = useState('');
  const [quarantinePurpose, setQuarantinePurpose] = useState('EXPORT');
  const [quarantineDays, setQuarantineDays]       = useState(21);
  const [vetOfficerName, setVetOfficerName]       = useState('');
  const [admissionNotes, setAdmissionNotes]       = useState('');

  useEffect(() => { void load(); }, [id]);

  async function load() {
    if (!id) return;
    const { data } = await supabase.from('movement_permits').select('*').eq('id', id).maybeSingle();
    setPermit(data);
    if (data?.vehicle_registration) setVehicleReg(data.vehicle_registration);
    setLoading(false);
  }

  function addAnimal() {
    if (!tagInput.trim()) return;
    setAnimals(prev => [...prev, {
      tag_number: tagInput.trim(), species: speciesInput,
      arrival_condition: conditionInput, notes: notesInput,
    }]);
    setTagInput(''); setNotesInput('');
  }

  function removeAnimal(i: number) {
    setAnimals(prev => prev.filter((_, idx) => idx !== i));
  }

  async function confirmArrival() {
    if (!permit || !facilityId || !facilityCode) return;
    if (animals.length === 0) { setError('Add at least one animal before confirming.'); return; }
    setSaving(true); setError(null);

    try {
      // 1. Create quarantine batch with arrival details
      const admissionDate  = new Date().toISOString().slice(0, 10);
      const completionDate = new Date(Date.now() + quarantineDays * 86400000).toISOString().slice(0, 10);
      const batchCode      = genCode(facilityCode);

      const { data: batch, error: batchErr } = await supabase
        .from('quarantine_batches')
        .insert({
          batch_code:               batchCode,
          facility_id:              facilityId,
          facility_code:            facilityCode,
          movement_permit_id:       permit.id,
          vehicle_reg:              vehicleReg || null,
          driver_name:              driverName || null,
          seal_number:              sealNumber || null,
          permit_qr_data:           permitQr || null,
          status:                   'ADMITTED',
          quarantine_purpose:       quarantinePurpose,
          pen_assignment:           penAssignment || null,
          admission_date:           admissionDate,
          quarantine_days:          quarantineDays,
          expected_completion_date: completionDate,
          animal_count:             animals.length,
          vet_officer_name:         vetOfficerName || null,
          notes:                    admissionNotes || null,
          created_by_id:            staffId,
          created_by_name:          staffName,
        })
        .select('id')
        .single();

      if (batchErr || !batch) throw new Error(batchErr?.message ?? 'Failed to create batch');

      // 2. Insert batch animals
      await supabase.from('quarantine_batch_animals').insert(
        animals.map(a => ({
          batch_id:          batch.id,
          facility_id:       facilityId,
          tag_number:        a.tag_number,
          species:           a.species,
          arrival_condition: a.arrival_condition,
          status:            a.arrival_condition === 'DEAD' ? 'DEAD' : 'ACTIVE',
          isolation_required: ['SICK', 'INJURED'].includes(a.arrival_condition),
          notes:             a.notes || null,
        }))
      );

      // 3. Mark permit as USED
      await supabase.from('movement_permits')
        .update({ status: 'USED', updated_at: new Date().toISOString() })
        .eq('id', permit.id);

      void navigate(`/quarantine/batches/${batch.id}`);
    } catch (e: unknown) {
      setError((e as Error).message);
      setSaving(false);
    }
  }

  if (loading) return <div className={s.loading}>Loading…</div>;
  if (!permit) return <div className={s.empty}>Movement permit not found.</div>;

  const healthy = animals.filter(a => a.arrival_condition === 'HEALTHY').length;
  const sick    = animals.filter(a => a.arrival_condition === 'SICK').length;
  const injured = animals.filter(a => a.arrival_condition === 'INJURED').length;
  const dead    = animals.filter(a => a.arrival_condition === 'DEAD').length;

  return (
    <div className={s.page}>
      <button className={s.backLink} onClick={() => void navigate('/quarantine/movements')}>← Back to Movement Permits</button>
      <div className={s.pageHeader}>
        <div>
          <h1 className={s.pageTitle}>Animal Arrival — {permit.permit_number}</h1>
          <p className={s.pageSub}>Record animals arriving under this movement permit</p>
        </div>
      </div>

      <div className={s.steps}>
        {[{ n:1, label:'Verify Permit' }, { n:2, label:'Scan Animals' }, { n:3, label:'Pen & Batch' }].map((st, i, arr) => (
          <>
            <div key={st.n} className={`${s.step} ${step === st.n ? s.active : step > st.n ? s.done : ''}`}>
              <div className={s.stepDot}>{step > st.n ? '✓' : st.n}</div>
              {st.label}
            </div>
            {i < arr.length - 1 && <div className={s.stepLine} />}
          </>
        ))}
      </div>

      {error && <div className={`${s.alert} ${s.alert_error}`}>⚠ {error}</div>}

      {/* Step 1: Verify Permit */}
      {step === 1 && (
        <div className={s.card}>
          <h3 className={s.cardTitle}>Permit &amp; Vehicle Verification</h3>
          <div className={s.kv} style={{ marginBottom: '1rem' }}>
            <div className={s.kvRow}><span className={s.kvKey}>Permit Number</span><span className={s.kvVal}>{permit.permit_number}</span></div>
            <div className={s.kvRow}><span className={s.kvKey}>Origin</span><span className={s.kvVal}>{permit.origin_premises_name ?? permit.origin_premises_code ?? '—'}</span></div>
            <div className={s.kvRow}><span className={s.kvKey}>Owner</span><span className={s.kvVal}>{permit.owner_name ?? '—'}</span></div>
            <div className={s.kvRow}><span className={s.kvKey}>Approved Animal Count</span><span className={s.kvVal}>{permit.animal_count ?? '—'}</span></div>
            <div className={s.kvRow}><span className={s.kvKey}>Valid Until</span><span className={s.kvVal}>{permit.valid_to ?? '—'}</span></div>
            {permit.conditions && <div className={s.kvRow}><span className={s.kvKey}>Conditions</span><span className={s.kvVal}>{permit.conditions}</span></div>}
          </div>
          <div className={s.fieldRow}>
            <div className={s.field}>
              <label className={s.label}>Vehicle Registration *</label>
              <input className={s.input} value={vehicleReg} onChange={e => setVehicleReg(e.target.value)} placeholder="e.g. SO-1234" />
            </div>
            <div className={s.field}>
              <label className={s.label}>Driver Name *</label>
              <input className={s.input} value={driverName} onChange={e => setDriverName(e.target.value)} placeholder="Full name" />
            </div>
          </div>
          <div className={s.fieldRow}>
            <div className={s.field}>
              <label className={s.label}>Container / Seal Number</label>
              <input className={s.input} value={sealNumber} onChange={e => setSealNumber(e.target.value)} placeholder="Seal #" />
            </div>
            <div className={s.field}>
              <label className={s.label}>Permit QR / Scan Data</label>
              <input className={s.input} value={permitQr} onChange={e => setPermitQr(e.target.value)} placeholder="Scan or enter QR data" />
            </div>
          </div>
          <div className={s.formActions}>
            <button className={`${s.btn} ${s.btn_primary}`}
              disabled={!vehicleReg.trim() || !driverName.trim()}
              onClick={() => setStep(2)}>Next: Scan Animals →</button>
          </div>
        </div>
      )}

      {/* Step 2: Scan Animals */}
      {step === 2 && (
        <div className={s.card}>
          <h3 className={s.cardTitle}>Animal Scanning &amp; Reconciliation</h3>
          <div className={`${s.alert} ${s.alert_info}`}>
            ℹ Approved: <strong>{permit.animal_count ?? '?'}</strong> animals — Scanned so far: <strong>{animals.length}</strong>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr 1fr auto', gap: '0.5rem', alignItems: 'end', marginBottom: '1rem' }}>
            <div className={s.field} style={{ margin: 0 }}>
              <label className={s.label}>RFID / Tag Number</label>
              <input className={s.input} value={tagInput} onChange={e => setTagInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && addAnimal()}
                placeholder="Scan or type tag…" autoFocus />
            </div>
            <div className={s.field} style={{ margin: 0 }}>
              <label className={s.label}>Species</label>
              <select className={s.select} value={speciesInput} onChange={e => setSpeciesInput(e.target.value)}>
                {['CATTLE','CAMEL','GOAT','SHEEP'].map(sp => <option key={sp}>{sp}</option>)}
              </select>
            </div>
            <div className={s.field} style={{ margin: 0 }}>
              <label className={s.label}>Condition</label>
              <select className={s.select} value={conditionInput}
                onChange={e => setConditionInput(e.target.value as AnimalEntry['arrival_condition'])}>
                {['HEALTHY','SICK','INJURED','DEAD'].map(c => <option key={c}>{c}</option>)}
              </select>
            </div>
            <div className={s.field} style={{ margin: 0 }}>
              <label className={s.label}>Notes</label>
              <input className={s.input} value={notesInput} onChange={e => setNotesInput(e.target.value)} placeholder="Optional" />
            </div>
            <button className={`${s.btn} ${s.btn_primary}`} onClick={addAnimal} style={{ marginBottom: '1rem' }}>Add</button>
          </div>

          {animals.length > 0 && (
            <>
              <div style={{ display: 'flex', gap: '1rem', marginBottom: '0.75rem', fontSize: '0.82rem' }}>
                <span>Healthy: <strong>{healthy}</strong></span>
                <span>Sick: <strong style={{ color: '#dc2626' }}>{sick}</strong></span>
                <span>Injured: <strong style={{ color: '#d97706' }}>{injured}</strong></span>
                <span>Dead: <strong style={{ color: '#64748b' }}>{dead}</strong></span>
              </div>
              <table>
                <thead><tr><th>#</th><th>Tag Number</th><th>Species</th><th>Condition</th><th>Notes</th><th></th></tr></thead>
                <tbody>
                  {animals.map((a, i) => (
                    <tr key={i}>
                      <td>{i + 1}</td>
                      <td><strong>{a.tag_number}</strong></td>
                      <td>{a.species}</td>
                      <td><span className={`${s.badge} ${s['badge_' + a.arrival_condition]}`}>{a.arrival_condition}</span></td>
                      <td>{a.notes || '—'}</td>
                      <td><button className={`${s.btn} ${s.btn_danger}`} onClick={() => removeAnimal(i)}>✕</button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          <div className={s.formActions}>
            <button className={`${s.btn} ${s.btn_outline}`} onClick={() => setStep(1)}>← Back</button>
            <button className={`${s.btn} ${s.btn_primary}`} disabled={animals.length === 0} onClick={() => setStep(3)}>
              Next: Confirm Batch →
            </button>
          </div>
        </div>
      )}

      {/* Step 3: Pen & Batch */}
      {step === 3 && (
        <div className={s.card}>
          <h3 className={s.cardTitle}>Batch &amp; Pen Allocation</h3>
          <div className={`${s.alert} ${s.alert_info}`}>
            ℹ {animals.length} animals received — {sick + injured > 0 ? `${sick + injured} require isolation pen.` : 'all in healthy condition.'}
          </div>
          <div className={s.fieldRow}>
            <div className={s.field}>
              <label className={s.label}>Main Pen Assignment</label>
              <input className={s.input} value={penAssignment} onChange={e => setPenAssignment(e.target.value)} placeholder="e.g. Pen A, Pen 3" />
            </div>
            <div className={s.field}>
              <label className={s.label}>Quarantine Purpose</label>
              <select className={s.select} value={quarantinePurpose} onChange={e => setQuarantinePurpose(e.target.value)}>
                {['EXPORT','IMPORT','DISEASE_CONTROL','ROUTINE'].map(p => <option key={p}>{p}</option>)}
              </select>
            </div>
          </div>
          <div className={s.fieldRow}>
            <div className={s.field}>
              <label className={s.label}>Quarantine Period (days)</label>
              <input className={s.input} type="number" min={1} max={180} value={quarantineDays}
                onChange={e => setQuarantineDays(Number(e.target.value))} />
            </div>
            <div className={s.field}>
              <label className={s.label}>Assigned Veterinary Officer</label>
              <input className={s.input} value={vetOfficerName} onChange={e => setVetOfficerName(e.target.value)}
                placeholder="Officer name" />
            </div>
          </div>
          <div className={s.field}>
            <label className={s.label}>Admission Notes</label>
            <textarea className={s.textarea} value={admissionNotes}
              onChange={e => setAdmissionNotes(e.target.value)} placeholder="Any additional observations…" />
          </div>
          <div className={s.formActions}>
            <button className={`${s.btn} ${s.btn_outline}`} onClick={() => setStep(2)}>← Back</button>
            <button className={`${s.btn} ${s.btn_success}`} disabled={saving} onClick={() => void confirmArrival()}>
              {saving ? 'Creating Batch…' : 'Confirm Arrival & Create Batch'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default AnimalArrivalPage;
